phi.waitForNetworkIdle({ timeoutMs: 6000 });
const cards = phi.js(() => {
  const anchors = Array.from(document.querySelectorAll('a[href*="/p/"]'));
  const seen = new Map();
  for (const a of anchors) {
    const href = a.getAttribute('href') || '';
    let text = (a.innerText || '').replace(/\s+/g, ' ').trim();
    // climb to a card-like ancestor for fuller text
    let el = a, card = null;
    for (let k = 0; k < 6 && el; k++) {
      el = el.parentElement;
      if (!el) break;
      const t = (el.innerText || '').replace(/\s+/g, ' ').trim();
      if (/\$\d/.test(t) && t.length > text.length) { card = t; break; }
    }
    const key = href.split('/-/')[1] || href;
    const cur = seen.get(key) || { href, texts: [] };
    if (text) cur.texts.push(text);
    if (card) cur.cardText = card;
    seen.set(key, cur);
  }
  return Array.from(seen.values()).slice(0, 80);
});
phi.keep("cards_raw", cards.length);
return { count: cards.length, cards: cards.slice(0, 30) };

